parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const client_code = (body.client_code || body.clientCode || '').trim();
if (!client_code) throw new Error('client_code is required');

// Pass through regeneration params if present
const regenerate = body.regenerate || false;
const num_needed = body.num_needed || 0;
const rejection_notes = (body.rejection_notes || '').trim();
const exclude_concepts = body.exclude_concepts || [];

return [{ json: { client_code, regenerate, num_needed, rejection_notes, exclude_concepts } }];

const items = $input.all();
if (!items || items.length === 0 || !items[0].json) {
  throw new Error('No client found. Check client_code in the Client Database.');
}
const row = items[0].json;
function c(v) { return v === undefined || v === null ? '' : String(v).trim(); }

const brief = {
  client_code: c(row.client_code),
  brand_name: c(row.brand_name),
  client_name: c(row.client_name),
  client_email: c(row.client_email),
  website_url: c(row.website_url),
  product_feature: c(row.product_feature),
  differentiator: c(row.differentiator),
  competitors: c(row.competitors),
  competitor_strengths: c(row.competitor_strengths),
  target_user: c(row.target_user),
  biggest_problem: c(row.biggest_problem),
  main_hesitation: c(row.main_hesitation),
  social_proof: c(row.social_proof),
  selling_proposition: c(row.selling_proposition),
  brand_personality: c(row.brand_personality),
  credibility_point: c(row.credibility_point),
  transformation: c(row.transformation),
  best_concepts: c(row.best_concepts),
  compliance: c(row.compliance),
  reference_ads: c(row.reference_ads),
  available_assets: c(row.available_assets),
  do_not_say: c(row.do_not_say),
  additional_notes: c(row.additional_notes),
  num_scripts: parseInt(c(row.num_scripts)) || 3
};

const required = ['brand_name', 'product_feature', 'target_user'];
const missing = required.filter(f => !brief[f]);
if (missing.length > 0) throw new Error('Brief missing: ' + missing.join(', '));

return [{ json: { brief, revision_count: 0 } }];

const brief = $('Validate Brief').first().json.brief;
const projectRecord = $input.first().json;
const project_id = projectRecord.id;

// Build search queries for SerpAPI
const search_queries = [
  { engine: 'google', q: `${brief.brand_name} review`, label: 'brand_review' },
  { engine: 'google', q: `${brief.product_feature} review`, label: 'product_review' },
  { engine: 'google', q: `${brief.brand_name} ${brief.product_feature} reddit`, label: 'reddit' },
  { engine: 'google', q: `site:amazon.com ${brief.product_feature} reviews`, label: 'amazon' },
  { engine: 'google', q: `site:facebook.com/ads/library ${brief.competitors || ''} OR ${brief.brand_name}`, label: 'competitor_ads' },
  { engine: 'youtube', search_query: `${brief.product_feature} UGC review`, label: 'youtube_ugc' },
  { engine: 'youtube', search_query: `${brief.brand_name} review`, label: 'youtube_brand' },
  { engine: 'youtube', search_query: `${brief.biggest_problem || ''} solution product`, label: 'youtube_problem' },
  { engine: 'google_videos', q: `${brief.product_feature} tiktok UGC viral`, label: 'tiktok' },
  { engine: 'google_videos', q: `${brief.product_feature} instagram reels UGC`, label: 'instagram' },
  { engine: 'google', q: `${brief.competitors || ''} ${brief.product_feature} comparison`, label: 'competitor_compare' },
];

return [{ json: { brief, project_id, search_queries } }];

// ============================================================
// Parse research output into structured Airtable records
// Extracts VOC quotes, insights, and reference videos
// With full select field normalization for Airtable
// ============================================================

const researchOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const brief = $('Build Research Prompt').first().json.brief;
const project_id = $('Build Research Prompt').first().json.project_id;

// ---- Normalization helpers ----
// Research source: valid Airtable options
function normalizeSource(raw) {
  const s = (raw || '').toLowerCase().trim();
  if (s.includes('reddit')) return 'Reddit';
  if (s.includes('amazon')) return 'Amazon';
  if (s.includes('forum')) return 'Forum';
  if (s.includes('tiktok')) return 'TikTok';
  if (s.includes('instagram')) return 'Instagram';
  if (s.includes('youtube')) return 'Google';
  if (s.includes('client brief')) return 'Google';
  return 'Google';
}

// Research category: valid = Pain, Desire, Objection, Proof, Language
function normalizeCategory(raw) {
  const s = (raw || '').toLowerCase().trim();
  if (s.includes('pain') || s.includes('frustrat') || s.includes('fear')) return 'Pain';
  if (s.includes('desire') || s.includes('want') || s.includes('wish')) return 'Desire';
  if (s.includes('objection') || s.includes('question') || s.includes('skeptic') || s.includes('doubt')) return 'Objection';
  if (s.includes('proof') || s.includes('social') || s.includes('testimonial') || s.includes('review')) return 'Proof';
  if (s.includes('language') || s.includes('phrase') || s.includes('slang')) return 'Language';
  // Map less common categories
  const map = { 'pain': 'Pain', 'desire': 'Desire', 'objection': 'Objection', 'proof': 'Proof', 'language': 'Language', 'trend': 'Desire' };
  return map[s] || 'Pain';
}

// Platform: valid = TikTok, Instagram Reels, YouTube Shorts, Facebook, Multi-platform
function normalizePlatform(url, rawPlatform) {
  if (url) {
    if (url.includes('tiktok.com')) return 'TikTok';
    if (url.includes('instagram.com')) return 'Instagram Reels';
    if (url.includes('youtube.com') || url.includes('youtu.be')) return 'YouTube Shorts';
    if (url.includes('facebook.com')) return 'Facebook';
  }
  const map = {
    'youtube': 'YouTube Shorts', 'youtube shorts': 'YouTube Shorts',
    'tiktok': 'TikTok', 'instagram': 'Instagram Reels',
    'instagram reels': 'Instagram Reels', 'facebook': 'Facebook',
    'video': 'TikTok', 'ad library': 'Facebook', 'meta': 'Facebook', 'multi-platform': 'Multi-platform'
  };
  return map[(rawPlatform || '').toLowerCase().trim()] || 'TikTok';
}

// Reference video format: valid = Talking Head, GRWM, Before-After, Unboxing, POV, Storytime, Routine, Transformation, Comparison, Green Screen, Testimonial Ad, Product Demo, Stitch/Duet
function normalizeFormat(raw) {
  const s = (raw || '').toLowerCase().trim();
  const map = {
    'talking head': 'Talking Head', 'grwm': 'GRWM', 'before-after': 'Before-After',
    'before/after': 'Before-After', 'unboxing': 'Unboxing', 'pov': 'POV',
    'storytime': 'Storytime', 'routine': 'Routine', 'transformation': 'Transformation',
    'comparison': 'Comparison', 'green screen': 'Green Screen',
    'testimonial ad': 'Testimonial Ad', 'testimonial': 'Testimonial Ad',
    'product demo': 'Product Demo', 'demo': 'Product Demo',
    'stitch/duet': 'Stitch/Duet', 'tutorial': 'Product Demo',
    'review': 'Product Demo', 'product review': 'Product Demo',
    'how-to': 'Product Demo', 'how to': 'Product Demo',
    'reaction': 'Talking Head', 'challenge': 'Transformation',
    'skit': 'Storytime', 'haul': 'Unboxing'
  };
  return map[s] || 'Product Demo';
}

// Reference video type: valid = Organic Viral, Paid Ad, UGC Ad, Creator Content, Product Review
function normalizeType(raw) {
  const s = (raw || '').toLowerCase().trim();
  const map = {
    'organic viral': 'Organic Viral', 'paid ad': 'Paid Ad', 'ugc ad': 'UGC Ad',
    'creator content': 'Creator Content', 'product review': 'Creator Content',
    'ugc': 'UGC Ad', 'organic': 'Organic Viral', 'ad': 'Paid Ad',
    'review': 'Creator Content', 'sponsored': 'Paid Ad'
  };
  return map[s] || 'Organic Viral';
}

// ---- Parse VOC quotes ----
const vocRecords = [];
const vocMatch = researchOutput.match(/=== VOC_QUOTES_START ===[\s\S]*?=== VOC_QUOTES_END ===/i);
if (vocMatch) {
  const lines = vocMatch[0].split('\n').filter(l => l.startsWith('VOC|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 5) {
      vocRecords.push({
        project_id: [project_id],
        research_type: 'VOC Quote',
        category: normalizeCategory(parts[1]),
        source: normalizeSource(parts[2]),
        relevance: (parts[3] || 'Medium').trim(),
        content: (parts[4] || '').trim()
      });
    }
  }
}

// ---- Parse insights ----
const insightRecords = [];
const insightMatch = researchOutput.match(/=== INSIGHTS_START ===[\s\S]*?=== INSIGHTS_END ===/i);
if (insightMatch) {
  const lines = insightMatch[0].split('\n').filter(l => l.startsWith('INSIGHT|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 6) {
      insightRecords.push({
        project_id: [project_id],
        research_type: 'Market Trend',
        source: normalizeSource(parts[2]),
        category: normalizeCategory(parts[3]),
        relevance: (parts[4] || 'Medium').trim(),
        content: (parts[5] || '').trim()
      });
    }
  }
}

// ---- Parse reference videos ----
const refRecords = [];
const refMatch = researchOutput.match(/=== REFERENCE_VIDEOS_START ===[\s\S]*?=== REFERENCE_VIDEOS_END ===/i);
if (refMatch) {
  const lines = refMatch[0].split('\n').filter(l => l.startsWith('REF|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 9) {
      let url = (parts[1] || '').trim();
      const isFake = !url || url.includes('placeholder') || url.includes('dQw4w9WgXcQ') || url.includes('example.com') || url.includes('mock_url') || url.length < 15;

      if (!isFake || (parts[5] || '').trim().length > 10) {
        refRecords.push({
          project_id: [project_id],
          url: isFake ? '' : url,
          platform: normalizePlatform(url, (parts[2] || '').trim()),
          type: normalizeType((parts[3] || '').trim()),
          format: normalizeFormat((parts[4] || '').trim()),
          hook: (parts[5] || '').trim(),
          why_it_works: (parts[6] || '').trim(),
          adaptation_idea: (parts[7] || '').trim(),
          engagement: (parts[8] || '').trim()
        });
      }
    }
  }
}

// Fallbacks
if (vocRecords.length === 0) {
  vocRecords.push({
    project_id: [project_id], research_type: 'VOC Quote', category: 'Pain',
    source: 'Google', relevance: 'High',
    content: 'No VOC quotes found during research phase.'
  });
}

if (refRecords.length === 0) {
  refRecords.push({
    project_id: [project_id], url: '', platform: 'TikTok', type: 'Organic Viral',
    format: 'Talking Head', hook: 'N/A',
    why_it_works: 'No reference videos found during research phase.',
    adaptation_idea: '', engagement: ''
  });
}

const allResearch = [...vocRecords, ...insightRecords];
return [{ json: { project_id, brief, research_records: allResearch, reference_records: refRecords, research_output: researchOutput, research_count: allResearch.length, reference_count: refRecords.length } }];

// ============================================================
// Split reference video records into individual items for Airtable
// ============================================================
const data = $('Parse Research Output').first().json;
const items = data.reference_records.map(record => ({ json: record }));
return items;

// ============================================================
// Wait for both Airtable stores to finish, then proceed
// Inject Meta Ad Library snapshots + TikTok Creative Center
// Only specific ad links, NOT generic search page URLs
// ============================================================
const data = $('Parse Research Output').first().json;

const refRecords = [...(data.reference_records || [])];
const existingUrls = new Set(refRecords.map(r => r.url).filter(Boolean));
const pid = data.project_id;
const brief = data.brief || {};

// Country code from brief
const countryMap = { 'india': 'IN', 'us': 'US', 'usa': 'US', 'uk': 'GB', 'united states': 'US', 'united kingdom': 'GB', 'canada': 'CA', 'australia': 'AU' };
const countryCode = countryMap[(brief.target_country || brief.country || 'india').toLowerCase()] || 'IN';

// --- Inject Meta Ad Library specific ad_snapshot_urls (competitor ads only) ---
try {
  const metaData = $('Parse Meta Ads').first().json;
  const metaAds = (metaData.allResults && metaData.allResults.meta_ad_library) || [];
  for (const ad of metaAds.slice(0, 8)) {
    if (ad.url && !existingUrls.has(ad.url)) {
      refRecords.push({
        project_id: [pid], url: ad.url, platform: 'Facebook', type: 'Paid Ad', format: 'Product Demo',
        hook: (ad.body || '').slice(0, 100) || 'Competitor ad \u2014 ' + (ad.title || ''),
        why_it_works: 'Active competitor ad on Meta \u2014 ' + (ad.title || 'Unknown'),
        adaptation_idea: '', engagement: ''
      });
      existingUrls.add(ad.url);
    }
  }
} catch(e) { /* Meta Ads node may not have run */ }

// --- Inject TikTok Creative Center link ---
const ttUrl = 'https://ads.tiktok.com/business/creativecenter/inspiration/topads/pc/en?period=30&region=' + countryCode;
if (!existingUrls.has(ttUrl)) {
  refRecords.push({
    project_id: [pid], url: ttUrl, platform: 'TikTok', type: 'Paid Ad', format: 'Product Demo',
    hook: (brief.product_feature || brief.brand_name || 'Product') + ' \u2014 TikTok Top Ads (last 30 days)',
    why_it_works: 'Browse top-performing TikTok ads in target market',
    adaptation_idea: '', engagement: ''
  });
}

return [{ json: {
  project_id: pid,
  brief: data.brief,
  research_output: data.research_output,
  reference_records: refRecords,
  research_count: data.research_count,
  reference_count: refRecords.length
} }];

// ============================================================
// Build Strategy Agent prompt with brief + research output
// Groups reference videos by platform for easy browsing
// ============================================================

const data = $('Merge Store Results').first().json;
const brief = data.brief;
const researchOutput = data.research_output;
const project_id = data.project_id;
const refRecords = data.reference_records || [];

// Regeneration mode support
const regenData = $('Extract Client Code').first().json;
const isRegeneration = regenData.regenerate || false;
const numNeeded = regenData.num_needed || 0;
const excludeNames = regenData.exclude_concepts || [];
const rejectionNotes = regenData.rejection_notes || '';

let numConcepts = Math.ceil(brief.num_scripts * 1.5);
if (isRegeneration && numNeeded > 0) {
  numConcepts = Math.ceil(numNeeded * 1.5);
}

// Group references by platform
const validRefs = refRecords.filter(r => r.url && r.url.length > 10);
const grouped = {};
for (const r of validRefs) {
  const plat = r.platform || 'Other';
  if (!grouped[plat]) grouped[plat] = [];
  grouped[plat].push(r);
}

// Build platform-grouped reference list
let refVideoList = '';
let idx = 1;
const platformOrder = ['YouTube Shorts', 'Facebook', 'TikTok', 'Instagram Reels', 'Multi-platform', 'Other'];
for (const plat of platformOrder) {
  if (!grouped[plat] || grouped[plat].length === 0) continue;
  const label = plat === 'Facebook' ? 'Meta Ad Library' : plat;
  refVideoList += '\n--- ' + label + ' ---\n';
  for (const r of grouped[plat]) {
    const isBrowse = r.url.includes('ads/library') || r.url.includes('creativecenter') || r.url.includes('ads.tiktok.com');
    const browseTag = isBrowse ? ' (Browse link)' : '';
    refVideoList += '[' + idx + '] ' + r.url + ' | Platform: ' + r.platform + ' | Format: ' + (r.format || 'N/A') + ' | Hook: "' + (r.hook || '').slice(0, 80) + '"' + browseTag + '\n';
    idx++;
  }
}

const prompt = `You have deep research from our Research Analyst. Now develop the creative strategy.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}
Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Personality: ${brief.brand_personality}
Social Proof: ${brief.social_proof}
Credibility: ${brief.credibility_point}
Best Concepts: ${brief.best_concepts || 'Not specified'}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Scripts Ordered: ${brief.num_scripts}
Concepts to Present: ${numConcepts}

== RESEARCH REPORT ==
${researchOutput}

== AVAILABLE REFERENCE VIDEOS & AD LIBRARY LINKS ==
These are REAL, verified reference videos and ad library links from the research phase.
${refVideoList || 'No reference videos available.'}

== YOUR TASK ==
Develop ${numConcepts} UNIQUE creative concepts.

CRITICAL RULES:
1. Output ONLY valid JSON with a "concepts" array.
2. For reference_video_url, you MUST use a URL from the AVAILABLE REFERENCE VIDEOS list above. Do NOT make up or hallucinate URLs. Each concept should use the reference video that best matches its creative direction.
3. If there are fewer reference videos than concepts, you may reuse URLs, but try to spread them across different concepts.

JSON format:
\`\`\`json
{
  "concepts": [
    {
      "concept_name": "The Skeptic Convert",
      "reference_video_url": "exact URL from reference list above",
      "reference_platform": "TikTok",
      "framework": "PAS",
      "hook_type": "controversy",
      "hook_text": "Stop buying vitamin C serums. Here's why.",
      "format": "Talking Head",
      "funnel_stage": "TOF",
      "virality_score": 8,
      "concept_pitch": "One-line pitch for the client",
      "emotional_journey": "frustration > curiosity > relief > desire",
      "target_objection": "They all oxidize and turn orange",
      "platform": "TikTok",
      "ab_test_pair": "Name of paired concept or null"
    }
  ]
}
\`\`\`

For EACH concept provide ALL fields listed above.

DIVERSITY RULES:
- Each concept MUST use a DIFFERENT framework + hook type combination
- At least 4 different UGC video formats
- Mix funnel stages: at least 2 TOF, 1-2 MOF, 1-2 BOF
- Mix platforms
- At least one concept under 20 seconds
- Include at least 1 A/B test pair

Output ONLY valid JSON.`;

// Add regeneration context if in regeneration mode
let finalPrompt = prompt;
if (isRegeneration && excludeNames.length > 0) {
  finalPrompt += `\n\n== REGENERATION MODE ==\nPreviously approved concepts (DO NOT duplicate these themes):\n${excludeNames.map((n, i) => (i+1) + '. ' + n).join('\n')}\n\nPM feedback on rejected concepts: "${rejectionNotes}"\n\nGenerate ${numConcepts} NEW concepts that address this feedback.\nEnsure they are thematically different from the approved ones above.`;
}

return [{ json: { prompt: finalPrompt, brief, project_id } }];

// ============================================================
// Parse Strategy Agent output into concept records for Airtable
// Handles: code fences, thinking tags, truncated JSON
// Full select field normalization
// ============================================================

const rawOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const project_id = $('Build Strategy Prompt').first().json.project_id;
const brief = $('Build Strategy Prompt').first().json.brief;

// Strip Gemini artifacts
let cleanOutput = rawOutput
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let concepts = [];

// Method 1: Direct parse
try {
  const parsed = JSON.parse(cleanOutput);
  concepts = parsed.concepts || [parsed];
} catch(e1) {
  // Method 2: Find concepts block
  const match = cleanOutput.match(/\{\s*"concepts"\s*:\s*\[[\s\S]*\]\s*\}/);
  if (match) {
    try {
      concepts = JSON.parse(match[0]).concepts || [];
    } catch(e2) { /* fall through */ }
  }

  // Method 3: Repair truncated JSON — extract individual complete objects
  if (concepts.length === 0) {
    const arrStart = cleanOutput.indexOf('"concepts"');
    if (arrStart > -1) {
      const bracketStart = cleanOutput.indexOf('[', arrStart);
      if (bracketStart > -1) {
        let fragment = cleanOutput.substring(bracketStart);
        let depth = 0;
        let objStart = -1;
        for (let i = 0; i < fragment.length; i++) {
          const ch = fragment[i];
          if (ch === '[' && depth === 0) { depth = 1; continue; }
          if (depth < 1) continue;
          if (ch === '{') { if (depth === 1) objStart = i; depth++; }
          else if (ch === '}') {
            depth--;
            if (depth === 1 && objStart >= 0) {
              try { concepts.push(JSON.parse(fragment.substring(objStart, i + 1))); } catch(e) {}
              objStart = -1;
            }
          }
        }
      }
    }
  }
}

// Fallback
if (concepts.length === 0) {
  concepts = [{
    concept_name: 'Concept from Strategy', framework: 'PAS',
    hook_type: 'Curiosity Gap', hook_text: 'Strategy output could not be parsed.',
    format: 'Talking Head', funnel_stage: 'TOF', virality_score: 5,
    concept_pitch: 'Strategy output could not be parsed into structured concepts.',
    emotional_journey: 'N/A', target_objection: 'N/A',
    platform: 'TikTok', ab_test_pair: null, reference_video_url: '', reference_platform: 'TikTok'
  }];
}

// ---- Normalization helpers ----
const hookTypeMap = { 'controversy': 'Controversy', 'controversial': 'Controversy', 'pov': 'POV', 'calling-out': 'Calling-Out', 'calling out': 'Calling-Out', 'callout': 'Calling-Out', 'negative': 'Negative', 'authority': 'Authority', 'expert': 'Authority', 'social-proof': 'Social Proof', 'social proof': 'Social Proof', 'curiosity-gap': 'Curiosity Gap', 'curiosity gap': 'Curiosity Gap', 'curiosity': 'Curiosity Gap', 'story': 'Story', 'storytelling': 'Story', 'narrative': 'Story', 'fear/urgency': 'Fear/Urgency', 'fear-urgency': 'Fear/Urgency', 'fear': 'Fear/Urgency', 'urgency': 'Fear/Urgency', 'fomo': 'Fear/Urgency', 'hot-take': 'Hot Take', 'hot take': 'Hot Take', 'whisper': 'Whisper/ASMR', 'whisper/asmr': 'Whisper/ASMR', 'asmr': 'Whisper/ASMR', 'text-first': 'Text-First', 'text first': 'Text-First', 'text': 'Text-First' };

// Format: extract keyword from description, map to valid Airtable select
function normalizeFormat(raw) {
  if (!raw) return 'Talking Head';
  const s = raw.toLowerCase().trim();
  // Direct matches first
  const directMap = {
    'talking head': 'Talking Head', 'grwm': 'GRWM', 'before-after': 'Before-After',
    'before/after': 'Before-After', 'unboxing': 'Unboxing', 'pov': 'POV',
    'storytime': 'Storytime', 'routine': 'Routine', 'transformation': 'Transformation',
    'comparison': 'Comparison', 'green screen': 'Green Screen',
    'testimonial ad': 'Testimonial Ad', 'product demo': 'Product Demo',
    'stitch/duet': 'Stitch/Duet'
  };
  if (directMap[s]) return directMap[s];
  // Keyword extraction for long descriptions
  if (s.includes('comparison') || s.includes('side-by-side') || s.includes('vs.') || s.includes('versus')) return 'Comparison';
  if (s.includes('before') && s.includes('after')) return 'Before-After';
  if (s.includes('pov') || s.includes('point of view')) return 'POV';
  if (s.includes('demo') || s.includes('demonstration') || s.includes('tutorial') || s.includes('how-to') || s.includes('how to')) return 'Product Demo';
  if (s.includes('unbox')) return 'Unboxing';
  if (s.includes('story') || s.includes('micro-story') || s.includes('narrative')) return 'Storytime';
  if (s.includes('testimonial') || s.includes('review')) return 'Testimonial Ad';
  if (s.includes('transform') || s.includes('challenge')) return 'Transformation';
  if (s.includes('talking head') || s.includes('reaction')) return 'Talking Head';
  if (s.includes('routine') || s.includes('grwm') || s.includes('get ready')) return 'GRWM';
  if (s.includes('green screen')) return 'Green Screen';
  return 'Product Demo';
}

// Platform: pick first valid platform from comma-separated list
function normalizePlatform(raw) {
  if (!raw) return 'TikTok';
  const platformMap = {
    'tiktok': 'TikTok', 'instagram reels': 'Instagram Reels', 'instagram': 'Instagram Reels',
    'facebook': 'Facebook', 'youtube shorts': 'YouTube Shorts', 'youtube': 'YouTube Shorts',
    'multi-platform': 'Multi-platform'
  };
  // If it's a simple value, direct map
  const simple = raw.toLowerCase().trim();
  if (platformMap[simple]) return platformMap[simple];
  // If comma-separated, pick the first valid one
  const parts = raw.split(',').map(p => p.trim().toLowerCase());
  for (const p of parts) {
    if (platformMap[p]) return platformMap[p];
  }
  return 'TikTok';
}

const norm = (val, map) => {
  if (!val) return null;
  const key = val.toLowerCase().trim();
  if (map[key]) return map[key];
