const err = $input.first().json;
let brand = 'Unknown', code = 'N/A';
try { const b = $('Validate Brief').first().json.brief; brand = b.brand_name; code = b.client_code; } catch(e) {}
return [{ json: { brand_name: brand, client_code: code, error_message: err.error?.message || err.message || 'Unknown', error_node: err.error?.node?.name || 'Unknown', created_at: new Date().toISOString() } }];

const data = $input.first().json;
const brief = data.brief;
const competitors = (brief.competitors || '').split(',').map(c => c.trim()).filter(Boolean);

// Search for product CATEGORY keywords (short, focused)
// Meta Ad Library works best with 1-3 word queries
const terms = [];

// Use product_feature but only first 3-4 words
if (brief.product_feature) {
  const words = brief.product_feature.split(/\s+/).slice(0, 4).join(' ');
  terms.push(words);
}

// Add industry keyword as fallback
if (brief.industry) {
  const industry = brief.industry.split(/\s+/).slice(0, 2).join(' ');
  if (!terms[0] || !terms[0].toLowerCase().includes(industry.toLowerCase())) {
    terms.push(industry);
  }
}

// Add valid competitor names
const skipTerms = ['no direct', 'none', 'n/a', 'not specified', 'not identified', 'no competitor'];
for (const comp of competitors) {
  if (!skipTerms.some(s => comp.toLowerCase().includes(s))) {
    terms.push(comp);
  }
}

// Use first term only (Ad Library search works best with focused queries)
const searchTerms = terms[0] || 'product review';

const countryMap = {
  'india': 'IN', 'us': 'US', 'usa': 'US', 'united states': 'US',
  'uk': 'GB', 'united kingdom': 'GB', 'canada': 'CA',
  'australia': 'AU', 'germany': 'DE', 'france': 'FR'
};
const briefCountry = (brief.target_country || brief.country || 'IN').toLowerCase().trim();
const countryCode = countryMap[briefCountry] || briefCountry.toUpperCase().substring(0, 2) || 'IN';

return [{ json: {
  ...data,
  meta_search_terms: searchTerms,
  meta_country: countryCode,
  competitor_names: competitors,
  brand_name_lower: (brief.brand_name || '').toLowerCase()
} }];

const data = $('Build Meta Ads Request').first().json;
const allResults = data.allResults;
const metaResponse = $input.first().json;
const brandNameLower = data.brand_name_lower || '';

// Parse Meta Ad Library response — only specific ad snapshots
const metaAds = [];
const adData = metaResponse.data || [];
for (const ad of adData.slice(0, 25)) {
  // Skip brand's own ads
  const pageName = (ad.page_name || '').toLowerCase();
  if (brandNameLower && pageName.includes(brandNameLower)) continue;

  const snapshotUrl = ad.ad_snapshot_url || '';
  if (!snapshotUrl) continue;

  metaAds.push({
    title: ad.page_name || 'Competitor Ad',
    url: snapshotUrl,
    body: Array.isArray(ad.ad_creative_bodies) ? ad.ad_creative_bodies[0] || '' : '',
    platform: 'Facebook',
    type: 'Paid Ad'
  });
}

allResults.meta_ad_library = metaAds;

return [{ json: { allResults, brief: data.brief, project_id: data.project_id } }];
